        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the use of `DB_AGG_CMD_SET` for setting the doorbell, which did not account for the possibility of doorbells being lost. This could lead to situations where the doorbell signal was not properly registered, especially when multiple signals were generated in quick succession. By not ensuring that the maximum value between the last and current doorbell values was set, the implementation risked missing important notifications in the RDMA operations.

        Commit message:
        RDMA/qedr: Fix doorbell setting

Change the doorbell setting so that the maximum value between the last and
current value is set. This is to avoid doorbells being lost.

Fixes: a7efd7773e31 ("qedr: Add support for PD,PKEY and CQ verbs")
Link: https://lore.kernel.org/r/20200902165741.8355-3-michal.kalderon@marvell.com
Signed-off-by: Michal Kalderon <michal.kalderon@marvell.com>
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>  

        Patch:

 int qedr_create_cq(struct ib_cq *ibcq, const struct ib_cq_init_attr *attr,
 		   struct ib_udata *udata)
 {
 	struct ib_device *ibdev = ibcq->device;
 	struct qedr_ucontext *ctx = rdma_udata_to_drv_context(
 		udata, struct qedr_ucontext, ibucontext);
 	struct qed_rdma_destroy_cq_out_params destroy_oparams;
 	struct qed_rdma_destroy_cq_in_params destroy_iparams;
 	struct qed_chain_init_params chain_params = {
 		.mode		= QED_CHAIN_MODE_PBL,
 		.intended_use	= QED_CHAIN_USE_TO_CONSUME,
 		.cnt_type	= QED_CHAIN_CNT_TYPE_U32,
 		.elem_size	= sizeof(union rdma_cqe),
 	};
 	struct qedr_dev *dev = get_qedr_dev(ibdev);
 	struct qed_rdma_create_cq_in_params params;
 	struct qedr_create_cq_ureq ureq = {};
 	int vector = attr->comp_vector;
 	int entries = attr->cqe;
 	struct qedr_cq *cq = get_qedr_cq(ibcq);
 	int chain_entries;
 	u32 db_offset;
 	int page_cnt;
 	u64 pbl_ptr;
 	u16 icid;
 	int rc;

 	DP_DEBUG(dev, QEDR_MSG_INIT,
 		 "create_cq: called from %s. entries=%d, vector=%d\n",
 		 udata ? "User Lib" : "Kernel", entries, vector);

 	if (entries > QEDR_MAX_CQES) {
 		DP_ERR(dev,
 		       "create cq: the number of entries %d is too high. Must be equal or below %d.\n",
 		       entries, QEDR_MAX_CQES);
 		return -EINVAL;
 	}

 	chain_entries = qedr_align_cq_entries(entries);
 	chain_entries = min_t(int, chain_entries, QEDR_MAX_CQES);
 	chain_params.num_elems = chain_entries;

 	/* calc db offset. user will add DPI base, kernel will add db addr */
 	db_offset = DB_ADDR_SHIFT(DQ_PWM_OFFSET_UCM_RDMA_CQ_CONS_32BIT);

 	if (udata) {
 		if (ib_copy_from_udata(&ureq, udata, min(sizeof(ureq),
 							 udata->inlen))) {
 			DP_ERR(dev,
 			       "create cq: problem copying data from user space\n");
 			goto err0;
 		}

 		if (!ureq.len) {
 			DP_ERR(dev,
 			       "create cq: cannot create a cq with 0 entries\n");
 			goto err0;
 		}

 		cq->cq_type = QEDR_CQ_TYPE_USER;

 		rc = qedr_init_user_queue(udata, dev, &cq->q, ureq.addr,
 					  ureq.len, true, IB_ACCESS_LOCAL_WRITE,
 					  1);
 		if (rc)
 			goto err0;

 		pbl_ptr = cq->q.pbl_tbl->pa;
 		page_cnt = cq->q.pbl_info.num_pbes;

 		cq->ibcq.cqe = chain_entries;
 		cq->q.db_addr = ctx->dpi_addr + db_offset;
 	} else {
 		cq->cq_type = QEDR_CQ_TYPE_KERNEL;

 		rc = dev->ops->common->chain_alloc(dev->cdev, &cq->pbl,
 						   &chain_params);
 		if (rc)
 			goto err0;

 		page_cnt = qed_chain_get_page_cnt(&cq->pbl);
 		pbl_ptr = qed_chain_get_pbl_phys(&cq->pbl);
 		cq->ibcq.cqe = cq->pbl.capacity;
 	}

 	qedr_init_cq_params(cq, ctx, dev, vector, chain_entries, page_cnt,
 			    pbl_ptr, &params);

 	rc = dev->ops->rdma_create_cq(dev->rdma_ctx, &params, &icid);
 	if (rc)
 		goto err1;

 	cq->icid = icid;
 	cq->sig = QEDR_CQ_MAGIC_NUMBER;
 	spin_lock_init(&cq->cq_lock);

 	if (udata) {
 		rc = qedr_copy_cq_uresp(dev, cq, udata, db_offset);
 		if (rc)
 			goto err2;

 		rc = qedr_db_recovery_add(dev, cq->q.db_addr,
 					  &cq->q.db_rec_data->db_data,
 					  DB_REC_WIDTH_64B,
 					  DB_REC_USER);
 		if (rc)
 			goto err2;

 	} else {
 		/* Generate doorbell address. */
 		cq->db.data.icid = cq->icid;
 		cq->db_addr = dev->db_addr + db_offset;
-		cq->db.data.params = DB_AGG_CMD_SET <<
+		cq->db.data.params = DB_AGG_CMD_MAX <<
 		    RDMA_PWM_VAL32_DATA_AGG_CMD_SHIFT;

 		/* point to the very last element, passing it we will toggle */
 		cq->toggle_cqe = qed_chain_get_last_elem(&cq->pbl);
 		cq->pbl_toggle = RDMA_CQE_REQUESTER_TOGGLE_BIT_MASK;
 		cq->latest_cqe = NULL;
 		consume_cqe(cq);
 		cq->cq_cons = qed_chain_get_cons_idx_u32(&cq->pbl);

 		rc = qedr_db_recovery_add(dev, cq->db_addr, &cq->db.data,
 					  DB_REC_WIDTH_64B, DB_REC_KERNEL);
 		if (rc)
 			goto err2;
 	}

 	DP_DEBUG(dev, QEDR_MSG_CQ,
 		 "create cq: icid=0x%0x, addr=%p, size(entries)=0x%0x\n",
 		 cq->icid, cq, params.cq_size);

 	return 0;

 err2:
 	destroy_iparams.icid = cq->icid;
 	dev->ops->rdma_destroy_cq(dev->rdma_ctx, &destroy_iparams,
 				  &destroy_oparams);
 err1:
 	if (udata) {
 		qedr_free_pbl(dev, &cq->q.pbl_info, cq->q.pbl_tbl);
 		ib_umem_release(cq->q.umem);
 		if (cq->q.db_mmap_entry)
 			rdma_user_mmap_entry_remove(cq->q.db_mmap_entry);
 	} else {
 		dev->ops->common->chain_free(dev->cdev, &cq->pbl);
 	}
 err0:
 	return -EINVAL;
 }



